Given an array of integers, the task is to find the length of the longest subsequence such that elements in the subsequence are consecutive integers, the consecutive numbers can be in any order. Examples:  Input: arr[] = [2, 6, 1, 9, 4, 5, 3]Output: 6Explanation:  The longest consecutive subsequence [2, 6, 1, 4, 5, 3].Input: arr[] = [1,1,1,2,2,3]Output: 3Explanation: The subsequence [1, 2,3] is the longest subsequence of consecutive elementsTry It YourselfTable of Content[Naive Approach] Using Sorting - O(n*log n) Time and O(1) Space[Expected Approach] Using Hashing - O(n) Time and O(n) Space[Naive Approach] Using Sorting - O(n*log n) Time and O(1) SpaceThe idea is to sort the array and find the longest subarray with consecutive elements. Initialize the consecutive count with 1 and start iterating over the sorted array from the second element.Sort the array in ascending order.Traverse the sorted array and skip duplicate elements.If the current element is one greater than the previous element, increment the current consecutive count and update the maximum count.Otherwise, reset the current consecutive count to 1.Return the maximum consecutive count.
            C++

    #include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int longestConsecutive(vector<int> &arr)
{

    // base case: if array is empty
    if (arr.empty())
        return 0;

    // sort the array
    sort(arr.begin(), arr.end());

    int res = 1, cnt = 1;

    // find the maximum length by traversing the array
    for (int i = 1; i < arr.size(); i++)
    {

        // Skip duplicates
        if (arr[i] == arr[i - 1])
            continue;

        // Check if the current element is equal
        // to previous element + 1
        if (arr[i] == arr[i - 1] + 1)
        {
            cnt++;
        }
        else
        {
            cnt = 1;
        }

        // Update the result
        res = max(res, cnt);
    }
    return res;
}

int main()
{
    vector<int> arr = {2, 6, 1, 9, 4, 5, 3};
    cout << longestConsecutive(arr);
    return 0;
}


